package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.view.inspector.WindowInspector;
import android.graphics.Rect;
import android.widget.TextView;
import java.io.PrintWriter;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Private exact-clock UI with fake scheduling only. All scheduler calls are injected; no alarm runtime may open. */
public class SnoozeUntilFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private AlarmEditorActivity activity;
    private String step="fixture admission";
    private void await(java.util.function.BooleanSupplier ready){assertTrue(step,device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){return ready.getAsBoolean();}},5000));}
    private View find(View root,String value,boolean description){if(description?value.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()):root instanceof TextView&&value.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View view=find(group.getChildAt(n),value,description);if(view!=null)return view;}return null;}
    private View focusedWindow(){View found=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(c.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getWidth()>0&&root.getHeight()>0){assertNull("One focused application window",found);found=root;}return found;}
    private void ready(){await(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()&&focusedWindow()==activity.getWindow().getDecorView());return yes[0];});}
    private void frame(View owner)throws Exception{CountDownLatch drawn=new CountDownLatch(1);i.runOnMainSync(()->{assertSame("Exact focused window before frame",owner,focusedWindow());owner.getViewTreeObserver().registerFrameCommitCallback(drawn::countDown);owner.invalidate();});assertTrue(step+": rendered owned frame",drawn.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame("Frame retains its exact focused window",owner,focusedWindow()));}
    private void require(String value,boolean description){step="require page "+value;ready();await(()->{boolean[] yes={false};i.runOnMainSync(()->{View target=find(activity.getWindow().getDecorView(),value,description);if(target==null)return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();yes[0]=target.isShown()&&target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return yes[0];});}
    private boolean hasText(String text){boolean[] found={false};i.runOnMainSync(()->found[0]=find(activity.getWindow().getDecorView(),text,false)!=null);return found[0];}
    private void input(View owner,String value,boolean description)throws Exception{
        step="single owned input "+value;
        await(()->{boolean[] ready={false};i.runOnMainSync(()->{if(focusedWindow()!=owner)return;View target=find(owner,value,description);if(target==null)return;while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();if(!target.isClickable()||!target.isEnabled())return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();ready[0]=target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return ready[0];});
        frame(owner);Rect screen=new Rect();i.runOnMainSync(()->{assertSame(owner,focusedWindow());View target=find(owner,value,description);assertNotNull(step,target);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();assertSame("Control belongs to exact decor",owner,target.getRootView());assertTrue(target.isClickable()&&target.isEnabled());Rect visible=new Rect();assertTrue(target.getGlobalVisibleRect(visible));assertEquals("Complete control width",target.getWidth(),visible.width());assertEquals("Complete control height",target.getHeight(),visible.height());assertTrue("48dp width",visible.width()>=Design.dp(c,48));assertTrue("48dp height",visible.height()>=Design.dp(c,48));int[] position=new int[2];target.getLocationOnScreen(position);screen.set(position[0],position[1],position[0]+target.getWidth(),position[1]+target.getHeight());});
        // Exactly one input. Never repeat a delivered action after an absent postcondition.
        assertTrue(step+": dispatched once",device.click(screen.centerX(),screen.centerY()));
    }
    private void click(String text)throws Exception{ready();input(activity.getWindow().getDecorView(),text,false);}
    private void clickDescription(String value)throws Exception{ready();input(activity.getWindow().getDecorView(),value,true);}
    private View durationDialog()throws Exception{step="await owned Snooze duration dialog";View[] owner={null};await(()->{i.runOnMainSync(()->{View root=focusedWindow();if(root!=null&&root!=activity.getWindow().getDecorView()&&find(root,"Options for Snooze duration",true)!=null)owner[0]=root;});return owner[0]!=null;});frame(owner[0]);return owner[0];}
    private void choose(View owner,String value,boolean description)throws Exception{input(owner,value,description);step="await exact selector detachment after "+value;await(()->!owner.isAttachedToWindow());ready();frame(activity.getWindow().getDecorView());}
    private void launch(Alarm alarm)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("route","snooze").putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Snooze & backup",false);}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Snooze & backup",false);}
    private void capture(String name)throws Exception{step="capture snooze-until-"+name;View[] root={null};i.runOnMainSync(()->root[0]=focusedWindow());assertNotNull(root[0]);frame(root[0]);File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"snooze-until-"+name+".png")));}
    private boolean failureCaptured;
    private void failure(Throwable problem){if(failureCaptured)return;failureCaptured=true;try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());try(PrintWriter out=new PrintWriter(new File(folder,"snooze-until-failure.txt"),"UTF-8")){out.println(step);problem.printStackTrace(out);}device.takeScreenshot(new File(folder,"snooze-until-failure.png"));device.dumpWindowHierarchy(new File(folder,"snooze-until-failure.xml"));}catch(Exception diagnostic){problem.addSuppressed(diagnostic);}}
    private static final class Fake implements SnoozeUntil.Port {String run="private-run",revision="private-revision";long wall=java.time.Instant.parse("2026-10-25T10:30:20Z").toEpochMilli(),elapsed=5000,deadline;int schedules;public SnoozeUntil.State state(){return new SnoozeUntil.State(run,revision,0,10,false,3,true,true,true,wall,elapsed,java.time.ZoneOffset.UTC);}public void schedule(long target){schedules++;assertEquals(0,deadline);deadline=target;}}
    private Dialog review;private SnoozeUntil offer;
    private View open(Fake fake)throws Exception{ready();i.runOnMainSync(()->{offer=new SnoozeUntil(fake.state());review=SnoozeUntilDialog.show(activity,offer,fake);});await(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=review.isShowing()&&focusedWindow()==review.getWindow().getDecorView());return yes[0];});return review.getWindow().getDecorView();}
    private void minute(View root,int value){i.runOnMainSync(()->{View field=find(root,"Minute",true);assertTrue(field instanceof android.widget.EditText);((android.widget.EditText)field).setText(""+value);});}
    private void error(View root,String message)throws Exception{step="await inline "+message;await(()->{boolean[] yes={false};i.runOnMainSync(()->{View text=find(root,message,false);if(text==null)return;text.requestRectangleOnScreen(new Rect(0,0,text.getWidth(),text.getHeight()),true);Rect shown=new Rect();yes[0]=text.getGlobalVisibleRect(shown)&&shown.height()==text.getHeight();});return yes[0];});}
    interface Work {void run(AlarmSkipFixture f)throws Exception;}
    private void fixture(Work work)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertEquals(0,Prefs.number(c,"checkPending",0));List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue("Only private configuration host; never alarm Activity/Service",a instanceof AlarmEditorActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);try(AlarmSkipFixture f=new AlarmSkipFixture()){try{Alarm config=f.load();config.enabled=false;config.inputs=config.inputs.chooseSnooze(true);config.snoozeMinutes=10;try(Store s=f.open()){s.save(config);}String before=f.load().json().toString();launch(f.load());work.run(f);assertEquals(before,f.load().json().toString());assertTrue(f.load().inputs.chooseSnooze);assertEquals(0,f.schedules);}catch(Exception|AssertionError problem){failure(problem);throw problem;}finally{i.runOnMainSync(()->{if(review!=null)review.dismiss();for(Activity a:owned)if(!a.isDestroyed())a.finish();});await(()->owned.stream().allMatch(Activity::isDestroyed));}}finally{app.unregisterActivityLifecycleCallbacks(callbacks);}}
    @Test public void exactClockErrorsAndExplicitConfirmationUseFakeDeadlineWithoutChangingStoredConfiguration()throws Exception{fixture(f->{Fake fake=new Fake();View root=open(fake);capture("initial");minute(root,30);input(root,"Snooze until this time",false);error(root,"Choose a later time today.");assertEquals(0,fake.schedules);capture("past");minute(root,41);input(root,"Snooze until this time",false);error(root,"Choose within 10 minutes from now.");assertEquals(0,fake.schedules);capture("too-late");minute(root,35);input(root,"Snooze until this time",false);await(()->!root.isAttachedToWindow());ready();assertEquals(1,fake.schedules);assertEquals(java.time.Instant.parse("2026-10-25T10:35:00Z").toEpochMilli(),fake.deadline);assertTrue(offer.completed());capture("confirmed");});}
    @Test public void cancelRecreationAndChangedOfferNeverScheduleOrRestoreAnAutomaticChoice()throws Exception{fixture(f->{Fake fake=new Fake();View cancel=open(fake);input(cancel,"Cancel",false);await(()->!cancel.isAttachedToWindow());ready();assertEquals(0,fake.schedules);capture("cancelled");View old=open(fake);SnoozeUntil revoked=offer;recreate();await(()->!old.isAttachedToWindow());assertNotNull(revoked.confirm(635,fake));assertEquals(0,fake.schedules);capture("recreated");View stale=open(fake);fake.revision="private-revision-changed";minute(stale,35);input(stale,"Snooze until this time",false);error(stale,"This snooze offer changed. Reopen Snooze.");assertEquals(0,fake.schedules);capture("stale");});}
}
